import{_ as n,a0 as o,w as r,s as u,I as s,x as e,a1 as p,A as i,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"所有人的 DevOps | LCTT x X-CMD","titleTemplate":false,"description":"所有人的 DevOps | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"所有人的 DevOps | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"所有人的 DevOps | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181121 DevOps is for everyone","title":"所有人的 DevOps","tag":"201812","desc":""},"relativePath":"201812/20181121 DevOps is for everyone.md","filePath":"[post].md"}'),v={name:"201812/20181121 DevOps is for everyone.md"};function a(f,t,D,m,O,g){const l=o("Link");return r(),u("div",null,[t[31]||(t[31]=s("h1",{id:"所有人的-devops",tabindex:"-1"},[e("所有人的 DevOps "),s("a",{class:"header-anchor",href:"#所有人的-devops","aria-label":"Permalink to “所有人的 DevOps”"},"​")],-1)),t[32]||(t[32]=s("blockquote",null,[s("p",null,"让一名非工程师来解释为什么你不必成为一位开发者或运维就能爱上 DevOps。")],-1)),t[33]||(t[33]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/team-game-play-inclusive-diversity-collaboration.png?itok=8sUXV7W1",alt:""})],-1)),s("p",null,[t[1]||(t[1]=e("我从未做过开发或运维的工作 —— 那怎么我在写一篇关于 ",-1)),p(l,{href:"https://opensource.com/resources/devops"},{default:i(()=>[...t[0]||(t[0]=[e("DevOps",-1)])]),_:1}),t[2]||(t[2]=e(" 的文章？我一直都对计算机和技术有兴趣。我还对社群、心理学以及帮助他人充满热情。当我第一次听到 DevOps 时，这个概念激起了我的兴趣，因为它看起来融合了很多我感兴趣的东西，即便我是不写代码的。",-1))]),t[34]||(t[34]=d('<p>我的第一台电脑是 TRS-80，我喜欢在上面编写 BASIC 程序。我只上过两门我的高中开设的计算机编程课程。若干年后，我创办了一家计算机公司。我定制邮件标签和信纸，并建立了一个数据库来存储地址。</p><p>问题是我并不能从写代码中获得享受。我想要教育和帮助人们，我没法将写代码看作这样的一个机会。是的，技术可以帮助人们并改变生活，但是写代码没有点燃我的热情。我需要对我的工作感到兴奋并做我喜欢的事情。</p><p>我发现我爱 DevOps。对我而言，DevOps 指的是：</p><ul><li>文化，而不是代码</li><li>过程，而不是结果</li><li>建立一个所有人可以持续提升的环境</li><li>沟通与合作，而不是独立工作</li></ul><p>归根结底，DevOps 是指成为社区工作的一部分，实现共同的目标。DevOps 融合了心理学、社群、技术。DevOps 不是一个职位名称，它是一种生活和工作的哲学。</p><h3 id="找到我的社群" tabindex="-1">找到我的社群 <a class="header-anchor" href="#找到我的社群" aria-label="Permalink to “找到我的社群”">​</a></h3>',6)),s("p",null,[t[4]||(t[4]=e("快四年前，我在西雅图参加了我的第一个 ",-1)),p(l,{href:"https://www.devopsdays.org/"},{default:i(()=>[...t[3]||(t[3]=[e("DevOps 日",-1)])]),_:1}),t[5]||(t[5]=e(" 会议。我感觉我找到了我的社群。我觉得受到了欢迎和接受，尽管我从事营销工作而且没有计算机科学文凭。我可以从心理学和技术中寻找乐趣。",-1))]),s("p",null,[t[7]||(t[7]=e("在 DevOps 日，我学到了 ",-1)),p(l,{href:"https://itrevolution.com/the-three-ways-principles-underpinning-devops/"},{default:i(()=>[...t[6]||(t[6]=[e("DevOps“三步工作法”",-1)])]),_:1}),t[8]||(t[8]=e(" —— 流动、反馈、持续实验和学习 —— 以及新（对我而言）的概念，如 Kaizen（改善）和 Kaikaku（改革）。随着我的学习深入，我发现我在说这样的话，“我是这样做的！我都不知道这样做还有个名字！”",-1))]),s("p",null,[p(l,{href:"https://en.wikipedia.org/wiki/Kaizen"},{default:i(()=>[...t[9]||(t[9]=[e("Kaizen（改善）",-1)])]),_:1}),t[11]||(t[11]=e("是持续改进和学习的实践。小的量变积累随着时间的推移可以引起质变。我发现它和卡罗尔·德韦克的",-1)),p(l,{href:"https://en.wikipedia.org/wiki/Mindset#Fixed_and_growth"},{default:i(()=>[...t[10]||(t[10]=[e("成长型思维",-1)])]),_:1}),t[12]||(t[12]=e("的想法很相似。人们不是生来就是专家。在某方面拥有经验需要花费时间、练习，以及常常还有失败。承认增量的改善对确保我们不会放弃是很有必要的。",-1))]),s("p",null,[t[14]||(t[14]=e("另一方面，",-1)),p(l,{href:"https://en.wikipedia.org/wiki/Kaikaku"},{default:i(()=>[...t[13]||(t[13]=[e("Kaikaku（改革）",-1)])]),_:1}),t[15]||(t[15]=e("的概念是指，长时间的小的改变有时不能起作用，你需要做一些完全的或破坏性的改变。在没有找到下份工作前就辞职或移居新城市就足够有破坏性 —— 是的，两者我都做过。但这些彻底的改变收获巨大。如果我没有辞职并休息一段时间，我也许不会接触到 DevOps。等我决定继续工作的时候，我一直听到 DevOps，我开始研究它。这引导我参加了我的第一个 DevOps 日，从那里我开始看到我的所有热情开始聚集。从那时起，我已经参加了五次 DevOps 日活动，并且定期撰写关于 DevOps 话题的文章。",-1))]),t[35]||(t[35]=s("h3",{id:"将三步工作法用到工作中",tabindex:"-1"},[e("将三步工作法用到工作中 "),s("a",{class:"header-anchor",href:"#将三步工作法用到工作中","aria-label":"Permalink to “将三步工作法用到工作中”"},"​")],-1)),t[36]||(t[36]=s("p",null,"改变是困难的，学习新事物可以听起来很吓人。DevOps 的三步工作法提供了一个管理改变的框架。比如：信息流动是怎样的？是什么驱动着你做出改变？一旦你认为一个改变是必需的，你如何获得这个改变是否正确的反馈？你如何知道你在取得进展？反馈是必要的，并且应该包含积极和有建设性的要素。困难的地方在于保证建设性的要素不要重于积极要素。",-1)),t[37]||(t[37]=s("p",null,"对我而言，第三步 —— 持续实验和学习 —— 是 DevOps 最重要的部分。有一个可以自由地实验和冒险的环境，人们可以获得意想不到的结果。有时这些结果是好的，有时不是太好 —— 但这没事。创建一个可以接受失败结果的环境可以鼓励人们冒险。我们都应该力争定期的持续实验和学习。",-1)),t[38]||(t[38]=s("p",null,"DevOps 的三步工作法提供了一个尝试，获得反馈，以及从错误中获取经验的方法。几年前，我的儿子告诉我，“我从来就没想做到最好，因为那样我就没法从我的错误中学到东西了。”我们都会犯错，从中获得经验帮助我们成长和改善。如果我们的文化不支持尝试和学习，我们就不会愿意去犯错。",-1)),t[39]||(t[39]=s("h3",{id:"成为社区的一部分",tabindex:"-1"},[e("成为社区的一部分 "),s("a",{class:"header-anchor",href:"#成为社区的一部分","aria-label":"Permalink to “成为社区的一部分”"},"​")],-1)),t[40]||(t[40]=s("p",null,"我已经在技术领域工作了超过 20 年，直到我发现 DevOps 社区前，我还经常感觉自己是个外行。如果你像我一样——对技术充满热情，但不是工程和运维那方面——你仍然可以成为 DevOps 的一部分，即便你从事的是销售、营销、产品营销、技术写作、支持或其他工作。DevOps 是属于所有人的。",-1)),t[41]||(t[41]=s("hr",null,null,-1)),s("p",null,[t[17]||(t[17]=e("via: ",-1)),p(l,{href:"https://opensource.com/article/18/11/how-non-engineer-got-devops"},{default:i(()=>[...t[16]||(t[16]=[e("https://opensource.com/article/18/11/how-non-engineer-got-devops",-1)])]),_:1})]),s("p",null,[t[22]||(t[22]=e("作者：",-1)),p(l,{href:"https://opensource.com/users/dawnparzych"},{default:i(()=>[...t[18]||(t[18]=[e("Dawn Parych",-1)])]),_:1}),t[23]||(t[23]=e(" 选题：",-1)),p(l,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[19]||(t[19]=[e("lujun9972",-1)])]),_:1}),t[24]||(t[24]=e(" 译者：",-1)),p(l,{href:"https://github.com/alim0x"},{default:i(()=>[...t[20]||(t[20]=[e("alim0x",-1)])]),_:1}),t[25]||(t[25]=e(" 校对：",-1)),p(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[21]||(t[21]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[28]||(t[28]=e("本文由 ",-1)),p(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[26]||(t[26]=[e("LCTT",-1)])]),_:1}),t[29]||(t[29]=e(" 原创编译，",-1)),p(l,{href:"https://linux.cn/"},{default:i(()=>[...t[27]||(t[27]=[e("Linux中国",-1)])]),_:1}),t[30]||(t[30]=e(" 荣誉推出",-1))])])}const w=n(v,[["render",a]]);export{x as __pageData,w as default};
